import 'package:flutter/material.dart'; import 'package:intl/intl.dart'; import '../services/data_service.dart';
class DashboardScreen extends StatelessWidget{const DashboardScreen({super.key});
 @override Widget build(BuildContext c)=>FutureBuilder<Map<String,dynamic>>(future:DataService.instance.dashboard(),builder:(c,s){if(s.hasError)return Center(child:Text('Erro: ${s.error}'));if(!s.hasData)return const Center(child:CircularProgressIndicator());final d=s.data!;final euro=NumberFormat.currency(locale:'pt_PT',symbol:'€');final items=[('Membros','${d['members']}',Icons.groups),('Prospects','${d['prospects']}',Icons.shield),('Saldo',euro.format(d['total_balance']),Icons.account_balance_wallet),('Quotas pendentes',euro.format(d['fee_outstanding']),Icons.receipt_long),('Eventos','${d['open_events']}',Icons.event),('Stock baixo','${d['low_stock']}',Icons.inventory)];return ListView(padding:const EdgeInsets.all(16),children:[Text('Resumo do clube',style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w900)),const SizedBox(height:12),Wrap(spacing:10,runSpacing:10,children:items.map((i)=>SizedBox(width:230,child:Card(child:ListTile(leading:CircleAvatar(child:Icon(i.$3)),title:Text(i.$1),subtitle:Text(i.$2,style:const TextStyle(fontSize:20,fontWeight:FontWeight.w900)))))).toList()),const SizedBox(height:20),const Card(child:ListTile(leading:Icon(Icons.notifications_active),title:Text('Alertas e tarefas pendentes'),subtitle:Text('Aniversários, aprovações, documentos, stock e pagamentos.')))]);});}
